ALTER TABLE users ADD COLUMN eight_hour_limit INTEGER NOT NULL DEFAULT 1;
ALTER TABLE sessions ADD COLUMN device_id TEXT;
CREATE TABLE login_devices (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),device_hash TEXT NOT NULL,device_label TEXT NOT NULL,country TEXT,ip_hash TEXT,created_at TEXT NOT NULL,last_seen_at TEXT NOT NULL, UNIQUE(user_id,device_hash));
CREATE TABLE signin_events (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),device_id TEXT REFERENCES login_devices(id),action TEXT NOT NULL,device_label TEXT NOT NULL,country TEXT,ip_hash TEXT,risk TEXT NOT NULL,created_at TEXT NOT NULL,reviewed_at TEXT);
CREATE INDEX signin_events_user ON signin_events(user_id,created_at);
CREATE TABLE clinical_admission_decisions (id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES care_admissions(id),patient_id TEXT NOT NULL REFERENCES patients(id),organization_id TEXT NOT NULL REFERENCES organizations(id),physician_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('admit','discharge')),reason TEXT NOT NULL,observations TEXT NOT NULL,decided_at TEXT NOT NULL,created_at TEXT NOT NULL,request_key TEXT UNIQUE NOT NULL,request_payload TEXT NOT NULL,UNIQUE(admission_id,kind));
CREATE TABLE medication_orders (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),organization_id TEXT NOT NULL REFERENCES organizations(id),branch_id TEXT NOT NULL REFERENCES branches(id),admission_id TEXT REFERENCES care_admissions(id),prescriber_id TEXT NOT NULL REFERENCES users(id),medicine TEXT NOT NULL,dose TEXT NOT NULL,route TEXT NOT NULL,frequency TEXT NOT NULL,interval_hours REAL,prn INTEGER NOT NULL DEFAULT 0,indication TEXT NOT NULL,instructions TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','stopped')),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,stopped_at TEXT,stop_reason TEXT,request_key TEXT UNIQUE NOT NULL,request_payload TEXT NOT NULL);
CREATE INDEX medication_patient ON medication_orders(patient_id,organization_id,created_at);
CREATE TABLE medication_administrations (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES medication_orders(id),author_id TEXT NOT NULL REFERENCES users(id),due_at TEXT,administered_at TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('given','omitted','refused','held')),dose TEXT NOT NULL,reason TEXT NOT NULL,observations TEXT NOT NULL,created_at TEXT NOT NULL,slot_key TEXT UNIQUE NOT NULL,request_key TEXT UNIQUE NOT NULL,request_payload TEXT NOT NULL);
CREATE TABLE ward_observations (id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES care_admissions(id),patient_id TEXT NOT NULL REFERENCES patients(id),organization_id TEXT NOT NULL REFERENCES organizations(id),author_id TEXT NOT NULL REFERENCES users(id),discipline TEXT NOT NULL,values_json TEXT NOT NULL,observations TEXT NOT NULL,observed_at TEXT NOT NULL,created_at TEXT NOT NULL,request_key TEXT UNIQUE NOT NULL,request_payload TEXT NOT NULL);
CREATE INDEX ward_observation_history ON ward_observations(admission_id,observed_at);
ALTER TABLE visit_observations ADD COLUMN observations TEXT NOT NULL DEFAULT '';
ALTER TABLE care_areas ADD COLUMN created_at TEXT;
ALTER TABLE care_areas ADD COLUMN updated_at TEXT;
ALTER TABLE admission_team_members ADD COLUMN created_at TEXT;
ALTER TABLE admission_team_members ADD COLUMN updated_at TEXT;
CREATE TABLE treatment_events (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),organization_id TEXT NOT NULL REFERENCES organizations(id),object_id TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE signin_attempt_limits (id TEXT PRIMARY KEY,attempt_count INTEGER NOT NULL,window_ends_at TEXT NOT NULL);
CREATE TABLE account_activity (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX account_activity_user ON account_activity(user_id,created_at);
ALTER TABLE visit_events ADD COLUMN reason TEXT NOT NULL DEFAULT '';
ALTER TABLE visit_followups ADD COLUMN resolution_reason TEXT NOT NULL DEFAULT '';
